#!/usr/bin/env bash
# Builds the puzuz .deb from built binaries with nfpm (packaging/nfpm.yaml).
#
# The binaries must be for this machine's architecture: the shell completions
# are generated by running `BIN_DIR/puzuz completions <shell>`. The package
# version is the workspace version (a pre-release 0.2.0-rc.1 becomes
# 0.2.0~rc.1 inside the package, so that it sorts before 0.2.0). The file is
# written as OUT_DIR/puzuz_<workspace version>_<arch>.deb (no `~`, which
# GitHub release assets cannot contain) and its path is printed.
#
# Usage: scripts/dist/build-package.sh BIN_DIR OUT_DIR [FORMAT]
#   FORMAT: deb (default; the only one so far)
# Uses `nfpm` from PATH, or downloads a pinned one (scripts/dist/get-nfpm.sh).
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
bin_dir="${1:?usage: $0 BIN_DIR OUT_DIR [FORMAT]}"
out="${2:?usage: $0 BIN_DIR OUT_DIR [FORMAT]}"
format="${3:-deb}"
[ "$format" = deb ] || { echo "unsupported package format: $format" >&2; exit 2; }

case "$(uname -m)" in
x86_64) arch=amd64 ;;
aarch64 | arm64) arch=arm64 ;;
*) echo "unsupported architecture: $(uname -m)" >&2; exit 1 ;;
esac
version="$(sed -n '/^\[workspace.package\]/,/^\[/s/^version = "\(.*\)"/\1/p' "$root/Cargo.toml")"
[ -n "$version" ] || { echo "cannot read the workspace version" >&2; exit 1; }

if command -v nfpm >/dev/null 2>&1; then
    nfpm="$(command -v nfpm)"
else
    nfpm="$("$root/scripts/dist/get-nfpm.sh" "$root/target/dist-tools")"
fi

stage="$(mktemp -d)"
trap 'rm -rf "$stage"' EXIT
mkdir -p "$stage/bin" "$stage/completions" "$stage/docs"
install -m 0755 "$bin_dir/puzuz" "$bin_dir/puzuz-helper" "$stage/bin/"
cp -r "$root/packaging" "$stage/"
cp "$root/README.md" "$root/LICENSE" "$stage/"
cp "$root/docs/install.md" "$root/docs/architecture.md" "$stage/docs/"
"$stage/bin/puzuz" completions bash >"$stage/completions/puzuz.bash"
"$stage/bin/puzuz" completions zsh >"$stage/completions/_puzuz"
"$stage/bin/puzuz" completions fish >"$stage/completions/puzuz.fish"

mkdir -p "$out"
out="$(cd "$out" && pwd)"
file="$out/puzuz_${version}_$arch.$format"
(cd "$stage" && PUZUZ_PKG_ARCH="$arch" PUZUZ_PKG_VERSION="$version" \
    "$nfpm" package --config packaging/nfpm.yaml --packager "$format" --target "$file" >&2)
echo "$file"
